onal Metrics'))?></h5><div class="table-responsive"><table class="table"><thead><tr><th><?=e(t('Date'))?></th><th><?=e(t('Transactions'))?></th><th><?=e(t('Completed'))?></th><th><?=e(t('Failed'))?></th><th><?=e(t('Volume'))?></th></tr></thead><tbody><?php foreach(array_reverse($daily) as $r):?><tr><td><?=$r['day']?></td><td><?=$r['transactions']?></td><td><?=$r['completed']?></td><td><?=$r['failed']?></td><td>$<?=number_format((float)$r['volume'],2)?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><script>const d=<?=json_encode($daily)?>,t=<?=json_encode($types)?>;new Chart(document.getElementById('volume'),{type:'line',data:{labels:d.map(x=>x.day),datasets:[{label:'Completed volume',data:d.map(x=>Number(x.volume)),tension:.25},{label:'Transactions',data:d.map(x=>Number(x.transactions)),yAxisID:'y1',tension:.25}]},options:{scales:{y:{beginAtZero:true},y1:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false}}}}});new Chart(document.getElementById('types'),{type:'doughnut',data:{labels:t.map(x=>x.type),datasets:[{data:t.map(x=>Number(x.volume))}]}});</script>
